<span class="line">        <span class="token keyword">this</span><span class="token punctuation">.</span>template <span class="token operator">=</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">getJson</span><span class="token punctuation">(</span><span class="token string">&quot;join_query_sql.json&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
